self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(VERSION).then((cache) => cache.addAll(FILES.map((f) => BASE + f))).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== VERSION).map((k) => caches.delete(k)))).then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
  if (request.mode === 'navigate') {
    // Seiten: neuester Stand aus dem Netz. Ohne Netz, oder wenn der Server eine Unterseite nicht kennt (GitHub Pages
    // antwortet dort mit 404), die gespeicherte App; die App wählt die Seite dann selbst.
    const cached = () => caches.match(BASE);
    event.respondWith(
      fetch(request)
        .then((response) => (response.ok ? response : cached().then((hit) => hit || response)))
        .catch(() => cached()),
    );
    return;
  }
  event.respondWith(
    caches.match(request, { ignoreSearch: true }).then(
      (hit) =>
        hit ||
        fetch(request).then((response) => {
          if (response.ok) {
            const copy = response.clone();
            caches.open(VERSION).then((cache) => cache.put(request, copy));
          }
          return response;
        }),
    ),
  );
});
